import type { SubcontractorCompanyStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface SubcontractorCompanyStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export const subcontractorCompanyStatusConfig: Record<SubcontractorCompanyStatus, SubcontractorCompanyStatusEntry> = {
  active: { label: 'Active', variant: 'success' },
  deactivated: { label: 'Deactivated', variant: 'destructive' },
};

const defaultStatus: SubcontractorCompanyStatusEntry = { label: '', variant: 'default' };

export function getSubcontractorCompanyStatus(status: SubcontractorCompanyStatus): SubcontractorCompanyStatusEntry {
  return subcontractorCompanyStatusConfig[status] ?? { ...defaultStatus, label: snakeCaseToCapitalizedCase(status) };
}

export const subcontractorCompanyStatusItems: SelectItem<SubcontractorCompanyStatus>[] = Object.entries(
  subcontractorCompanyStatusConfig
).map(([value, { label }]) => ({ value: value as SubcontractorCompanyStatus, name: label }));
